def search7(topn=25, AYs=None, AXs=None):
    COLMASK=(1<<62)-1
    def mk(rows,top,left):
        m=0
        for dr,cm in rows:
            rr=top+dr
            if not(0<=rr<64): continue
            v=((cm<<left)&COLMASK) if left>=0 else ((cm>>(-left))&COLMASK)
            if v: m|=v<<(64*rr)
        return m
    B,dots=fp3(current_frame); F=B|dots
    out={}
    g=grid(current_frame); Ym=0
    for r in range(64):
        for c in range(62):
            if g[r][c]=='Y': Ym|=1<<(r*64+c)
    for name,pred in [('BR',lambda p:p[1]>=40),('BL',lambda p:p[1]<40)]:
        N=norm({p for p in F if pred(p)})
        rows,h,w=pat2(N)
        M={}
        for R in range(-h,64,3):
            for C in range(-w,64,3): M[(R,C)]=mk(rows,R,C)
        out[name]=(M,h,w)
    if AYs is None: AYs=[a for a in range(1,64,3)]
    if AXs is None: AXs=[a for a in range(1,64,3)]
    sols=[]
    for AY in AYs:
        for AX in AXs:
            cand={}
            for name,(M,h,w) in out.items():
                lst=[]
                for (R,C),m in M.items():
                    R2=2*AY-R-h; C2=2*AX-C-w
                    u=m|M.get((R2,C),0)|M.get((R,C2),0)|M.get((R2,C2),0)
                    lst.append((bin(u&Ym).count('1'),R,C,u))
                lst.sort(reverse=True)
                cand[name]=lst[:topn]
            for a in cand['BR']:
                for b in cand['BL']:
                    if ((a[3]|b[3])&Ym)==Ym:
                        sols.append((AY,AX,a[1],a[2],b[1],b[2]))
            if sols: return sols,out
    return sols,out
