def l4plan(tmax=20.0):
    import time, itertools
    from collections import deque, defaultdict
    t0=time.time()
    g=current_frame.ascii.split('\n')
    bad=set(); blk=set()
    for r in range(64):
        for c in range(1,64):
            v=g[r][c]
            if v in 'Sg': bad.add((r,c))
            elif v=='B': blk.add((r,c))
    D={p:0 for p in bad}; q=deque()
    for (r,c) in bad:
        for d in ((1,0),(-1,0),(0,1),(0,-1)):
            n=(r+d[0],c+d[1])
            if n not in D and 0<=n[0]<64 and 0<=n[1]<64: D[n]=1; q.append(n)
    while q:
        r,c=q.popleft()
        for d in ((1,0),(-1,0),(0,1),(0,-1)):
            n=(r+d[0],c+d[1])
            if n not in D and 0<=n[0]<64 and 0<=n[1]<64: D[n]=D[(r,c)]+1; q.append(n)
    def dd(p): return D.get(p,99)
    ringc={}
    for ctr in [(8,20),(12,50),(17,12),(29,14),(28,53),(49,36),(54,17),(54,55)]:
        cr,cc=ctr
        ringc[ctr]={(cr-3,cc-1),(cr-3,cc+1),(cr-2,cc-2),(cr-2,cc+2),(cr-1,cc-3),(cr-1,cc+3),
                    (cr+1,cc-3),(cr+1,cc+3),(cr+2,cc-2),(cr+2,cc+2),(cr+3,cc-1),(cr+3,cc+1)}
    rc=set().union(*ringc.values())
    def df(cr,cc): return {(cr+dr,cc+dc) for dr in range(-2,3) for dc in range(-2,3) if abs(dr)+abs(dc)<=2}
    def ff(cr,cc): return {(cr+dr,cc+dc) for dr in (-2,-1,0,1,2) for dc in (-2,-1,0,1,2) if not(abs(dr)==2 and abs(dc)==2)}
    def dfok(cr,cc):
        if (cr,cc) not in blk or dd((cr,cc))<3: return False
        for (r,c) in df(cr,cc):
            if 0<=r<64 and 0<=c<64 and (r,c) in rc: return False
        return True
    def ffok(cr,cc):
        for (r,c) in ff(cr,cc):
            if not(0<=r<64 and 0<=c<64): return False
            if (r,c) in bad or (r,c) in rc: return False
        return True
    C=[(r,c) for r in range(64) for c in range(1,64) if dfok(r,c)]
    CS=set(C)
    chains={'p':[(6,39),(20,23)],'N':[(36,17),(47,10),(52,27)],'b':[(36,46),(52,46)]}
    goals={'p':(49,36),'N':(12,50),'b':(54,17)}
    def sep(cs): return all(abs(x[0]-y[0])+abs(x[1]-y[1])>=5 for x,y in itertools.combinations(cs,2))
    def sols_for(ch,maxn=12):
        mem=chains[ch]; k=len(mem); tot=(goals[ch][0]*k,goals[ch][1]*k)
        sum0=(sum(m[0] for m in mem),sum(m[1] for m in mem))
        out=[]; seen=set()
        def check(key):
            for assign in itertools.permutations(key):
                ds=[(assign[i][0]-mem[i][0],assign[i][1]-mem[i][1]) for i in range(k)]
                for order in itertools.permutations(range(k)):
                    s=sum0; ok=True
                    for i in order:
                        s=(s[0]+ds[i][0],s[1]+ds[i][1])
                        if not ffok(s[0]//k,s[1]//k): ok=False; break
                    if ok: return (assign,order)
            return None
        if k==2:
            for a in C:
                b=(tot[0]-a[0],tot[1]-a[1])
                if b not in CS or a>=b: continue
                if not sep([a,b]): continue
                key=(a,b) if a<b else (b,a)
                if key in seen: continue
                seen.add(key)
                r=check(key)
                if r: out.append((min(dd(a),dd(b)),r))
        else:
            pairs=defaultdict(list)
            for a,b in itertools.combinations(C,2):
                if abs(a[0]-b[0])+abs(a[1]-b[1])<5: continue
                pairs[(a[0]+b[0],a[1]+b[1])].append((a,b))
            for s,lst in pairs.items():
                if time.time()-t0>tmax: break
                t=(tot[0]-s[0],tot[1]-s[1])
                if t not in pairs: continue
                for a,b in lst[:12]:
                    for c2,d2 in pairs[t][:12]:
                        cells=[a,b,c2]
                        if len(set(cells))<3 or not sep(cells): continue
                        key=tuple(sorted(cells))
                        if key in seen: continue
                        seen.add(key)
                        r=check(key)
                        if r: out.append((min(dd(x) for x in key),r))
        out.sort(key=lambda x:-x[0])
        return out[:maxn]
    S={ch:sols_for(ch) for ch in ('p','b','N')}
    print('nsols',{k:len(v) for k,v in S.items()})
    def sim(och, pick):
        pos={ch:list(chains[ch]) for ch in chains}; cur=('p',1); clicks=[]
        def flw(ch):
            ps=pos[ch]; return (sum(p[0] for p in ps)//len(ps), sum(p[1] for p in ps)//len(ps))
        def occ():
            s=set()
            for ch in pos:
                for p in pos[ch]: s|=df(*p)
                s|=ff(*flw(ch))
            return s
        for ch in och:
            assign,ordr=pick[ch]
            for mi in ordr:
                t=assign[mi]
                if pos[ch][mi]==t: continue
                if cur!=(ch,mi):
                    clicks.append(('S',pos[ch][mi])); cur=(ch,mi)
                if t not in blk or t in occ(): return None
                old=pos[ch][mi]; pos[ch][mi]=t
                if not ffok(*flw(ch)): pos[ch][mi]=old; return None
                clicks.append(('M',t))
        for ch in chains:
            if flw(ch)!=goals[ch]: return None
        return clicks
    best=None
    idx={'p':range(len(S['p'])),'b':range(len(S['b'])),'N':range(len(S['N']))}
    for och in itertools.permutations(['p','N','b']):
        for i in idx['p']:
            for j in idx['b']:
                for n in idx['N']:
                    pick={'p':S['p'][i][1],'b':S['b'][j][1],'N':S['N'][n][1]}
                    r=sim(och,pick)
                    if r and (best is None or len(r)<len(best[1])): best=(och,r)
        if best: break
    return best
